/** A setting's fields: a known key, its value, and for a dated setting an optional from-date (yyyy-mm-dd). The terms are a whole number of days. A grade's terms (terms-<grade>) are a whole number of days, or blank for the sheet's terms. A grade's grace (grace-<grade>) is a whole number of days, or blank for none. The floor is an amount with up to two decimals. The clerk limit is an amount with up to two decimals, or blank for no limit. The late percent is a number with up to two decimals. The policy date is a date (yyyy-mm-dd), or blank for the sheet's today. Period numbering from is a date, or blank for off. The entry date is a date, or blank for off. The grace days are a whole number of days, or blank for off. The cap is an amount with up to two decimals, or blank for none. The proof threshold is an amount with up to two decimals, or blank for none. A grade's proof threshold (proof-threshold-<grade>) is an amount with up to two decimals, or blank for the sheet's. The note threshold is an amount with up to two decimals, or blank for none. The pot is an amount with up to two decimals, or blank for none. The parent is a sheet id, or blank for none. A permission (perm-<action>) is a comma separated list of roles, or blank for the standing rule. */
public class ValidateSetting {

    private static final Pattern AMOUNT = Pattern.compile("\\d{1,10}(\\.\\d{1,2})?");
    private static final Pattern DAYS = Pattern.compile("\\d{1,5}");
    private static final Pattern MONTH = Pattern.compile("\\d{1,2}");

    public void validate(@RequestBody SettingRequest request, Out<SettingInput> setting, Out<ChangedBy> changedBy)
            throws BadRequestException {
        ChangedBy by = ChangedBy.of(request == null ? null : request.by());
        String key = request == null || request.key() == null ? "" : request.key().trim();
        String text = request == null || request.value() == null ? "" : request.value().trim();
        String fromText = request == null || request.from() == null ? "" : request.from().trim();
        java.time.LocalDate from = null;
        if (!fromText.isEmpty()) {
            if (!Setting.isDated(key)) {
                throw new BadRequestException("The " + key + " setting is not dated; leave its from-date blank");
            }
            try {
                from = java.time.LocalDate.parse(fromText);
            } catch (java.time.format.DateTimeParseException e) {
                throw new BadRequestException("A from-date is a date (yyyy-mm-dd), or blank for the sheet's today");
            }
        }
        if (Setting.TERMS.equals(key)) {
            if (!DAYS.matcher(text).matches()) {
                throw new BadRequestException("Terms are a whole number of days");
            }
            setting.set(new SettingInput(key, String.valueOf(Integer.parseInt(text)), from));
            changedBy.set(by);
            return;
        }
        if (key.startsWith(Setting.TERMS_OF_GRADE) && Setting.GRADES.contains(key.substring(Setting.TERMS_OF_GRADE.length()))) {
            if (!text.isEmpty() && !DAYS.matcher(text).matches()) {
                throw new BadRequestException("A grade's terms are a whole number of days, or blank for the sheet's terms");
            }
            setting.set(new SettingInput(key, text.isEmpty() ? null : String.valueOf(Integer.parseInt(text)), from));
            changedBy.set(by);
            return;
        }
        if (key.startsWith(Setting.GRACE_OF_GRADE) && Setting.GRADES.contains(key.substring(Setting.GRACE_OF_GRADE.length()))) {
            if (!text.isEmpty() && !DAYS.matcher(text).matches()) {
                throw new BadRequestException("A grade's grace is a whole number of days, or blank for none");
            }
            setting.set(new SettingInput(key, text.isEmpty() ? null : String.valueOf(Integer.parseInt(text)), from));
            changedBy.set(by);
            return;
        }
        if (Setting.FLOOR.equals(key)) {
            if (!AMOUNT.matcher(text).matches()) {
                throw new BadRequestException("A floor is an amount with up to two decimals");
            }
            setting.set(new SettingInput(key, new BigDecimal(text).setScale(2).toPlainString(), from));
            changedBy.set(by);
            return;
        }
        if (Setting.LATE_PCT.equals(key)) {
            if (!AMOUNT.matcher(text).matches()) {
                throw new BadRequestException("A late percent is a number with up to two decimals");
            }
            setting.set(new SettingInput(key, new BigDecimal(text).setScale(2).toPlainString(), from));
            changedBy.set(by);
            return;
        }
        if (Setting.POLICY_DATE.equals(key)) {
            String date = null;
            if (!text.isEmpty()) {
                try {
                    date = java.time.LocalDate.parse(text).toString();
                } catch (java.time.format.DateTimeParseException e) {
                    throw new BadRequestException("A policy date is a date (yyyy-mm-dd), or blank for the sheet's today");
                }
            }
            setting.set(new SettingInput(key, date, from));
            changedBy.set(by);
            return;
        }
        if (Setting.PERIOD_NUMBERING_FROM.equals(key)) {
            String date = null;
            if (!text.isEmpty()) {
                try {
                    date = java.time.LocalDate.parse(text).toString();
                } catch (java.time.format.DateTimeParseException e) {
                    throw new BadRequestException("Period numbering from is a date (yyyy-mm-dd), or blank for off");
                }
            }
            setting.set(new SettingInput(key, date, from));
            changedBy.set(by);
            return;
        }
        if (Setting.ENTRY_DATE.equals(key)) {
            String date = null;
            if (!text.isEmpty()) {
                try {
                    date = java.time.LocalDate.parse(text).toString();
                } catch (java.time.format.DateTimeParseException e) {
                    throw new BadRequestException("An entry date is a date (yyyy-mm-dd), or blank for off");
                }
            }
            setting.set(new SettingInput(key, date, from));
            changedBy.set(by);
            return;
        }
        if (Setting.GRACE_DAYS.equals(key)) {
            if (!text.isEmpty() && !DAYS.matcher(text).matches()) {
                throw new BadRequestException("Grace days are a whole number of days, or blank for off");
            }
            setting.set(new SettingInput(key, text.isEmpty() ? null : String.valueOf(Integer.parseInt(text)), from));
            changedBy.set(by);
            return;
        }
        if (Setting.FISCAL_START_MONTH.equals(key)) {
            if (!MONTH.matcher(text).matches() || Integer.parseInt(text) < 1 || Integer.parseInt(text) > 12) {
                throw new BadRequestException("A fiscal start month is a month from 1 to 12");
            }
            setting.set(new SettingInput(key, String.valueOf(Integer.parseInt(text)), from));
            changedBy.set(by);
            return;
        }
        if (Setting.CAP.equals(key)) {
            String value = null;
            if (!text.isEmpty()) {
                if (!AMOUNT.matcher(text).matches()) {
                    throw new BadRequestException("A cap is an amount with up to two decimals, or blank for none");
                }
                value = new BigDecimal(text).setScale(2).toPlainString();
            }
            setting.set(new SettingInput(key, value, from));
            changedBy.set(by);
            return;
        }
        if (Setting.PROOF_THRESHOLD.equals(key)) {
            String value = null;
            if (!text.isEmpty()) {
                if (!AMOUNT.matcher(text).matches()) {
                    throw new BadRequestException("A proof threshold is an amount with up to two decimals, or blank for none");
                }
                value = new BigDecimal(text).setScale(2).toPlainString();
            }
            setting.set(new SettingInput(key, value, from));
            changedBy.set(by);
            return;
        }
        if (key.startsWith(Setting.PROOF_THRESHOLD_OF_GRADE)
                && Setting.GRADES.contains(key.substring(Setting.PROOF_THRESHOLD_OF_GRADE.length()))) {
            String value = null;
            if (!text.isEmpty()) {
                if (!AMOUNT.matcher(text).matches()) {
                    throw new BadRequestException("A grade's proof threshold is an amount with up to two decimals, or blank for the sheet's");
                }
                value = new BigDecimal(text).setScale(2).toPlainString();
            }
            setting.set(new SettingInput(key, value, from));
            changedBy.set(by);
            return;
        }
        if (Setting.NOTE_THRESHOLD.equals(key)) {
            String value = null;
            if (!text.isEmpty()) {
                if (!AMOUNT.matcher(text).matches()) {
                    throw new BadRequestException("A note threshold is an amount with up to two decimals, or blank for none");
                }
                value = new BigDecimal(text).setScale(2).toPlainString();
            }
            setting.set(new SettingInput(key, value, from));
            changedBy.set(by);
            return;
        }
        if (Setting.POT.equals(key)) {
            String value = null;
            if (!text.isEmpty()) {
                if (!AMOUNT.matcher(text).matches()) {
                    throw new BadRequestException("A pot is an amount with up to two decimals, or blank for none");
                }
                value = new BigDecimal(text).setScale(2).toPlainString();
            }
            setting.set(new SettingInput(key, value, from));
            changedBy.set(by);
            return;
        }
        if (Setting.PARENT.equals(key)) {
            if (text.length() > 200) {
                throw new BadRequestException("A parent is a sheet id, or blank for none");
            }
            setting.set(new SettingInput(key, text.isEmpty() ? null : text, from));
            changedBy.set(by);
            return;
        }
        if (Setting.isPermission(key)) {
            String value = null;
            if (!text.isEmpty()) {
                java.util.List<String> roles = java.util.Arrays.stream(text.split(",", -1)).map(String::trim).toList();
                if (roles.stream().anyMatch(r -> !r.equals(Role.CLERK) && !r.equals(Role.STEWARD))) {
                    throw new BadRequestException("A permission is a comma separated list of roles (clerk, steward), or blank for the standing rule");
                }
                value = String.join(",", roles);
            }
            setting.set(new SettingInput(key, value, from));
            changedBy.set(by);
            return;
        }
        if (!Setting.CLERK_LIMIT.equals(key)) {
            throw new BadRequestException("No such setting: " + key);
        }
        String value = null;
        if (!text.isEmpty()) {
            if (!AMOUNT.matcher(text).matches()) {
                throw new BadRequestException("A clerk limit is an amount with up to two decimals, or blank for no limit");
            }
            value = new BigDecimal(text).setScale(2).toPlainString();
        }
        setting.set(new SettingInput(key, value, from));
        changedBy.set(by);
    }
}
package net.officefloor.hq.app.access;

import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetResponse;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Sets the setting: a dated one records its value from the from-date given (the sheet's today when none was), keeping the others. */
public class ApplySetting {
    public void apply(@Val SheetResponse sheet, @Val SettingInput input, SettingRepository repository,
            SheetRepository sheets, Out<Setting> setting) {
        if (!Setting.isDated(input.key())) {
            setting.set(repository.set(sheet.id(), input.key(), input.value()));
            return;
        }
        repository.setFrom(sheet.id(), input.key(), input.from() != null ? input.from() : sheets.today(sheet.id()),
                input.value());
        setting.set(new Setting(sheet.id(), input.key(), input.value(), input.from()));
    }
}
package net.officefloor.hq.app.access;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Val;

public class RecordSettingChanged {
    public void record(@Val Setting setting, @Val ChangedBy by, Audit audit) {
        audit.record("SETTING_CHANGED sheet=" + setting.sheetId() + " by=" + by.name() + " key=" + setting.key()
                + " value=" + (setting.value() == null ? "" : setting.value())
                + (setting.from() == null ? "" : " from=" + setting.from()));
    }
}
// a person's due-total may be, and the proof threshold (blank: none), the due above which a claim needs a proof before
// it is settled or approved, and each grade's proof threshold (blank: the sheet's), the one a claim of that grade on its
// date takes in its place, and the permission matrix: for each of open, settle, void, reassign, close and reopen, the
// roles that may take it (blank: the standing rule, shown as the placeholder), and the parent sheet (blank: none), whose rates (then its parent's, up to three levels up) stand in for a grade without one in force on a date. Every setting but the policy date, period numbering from, the entry date, the grace days, the pot, the parent and the permissions is dated: saving it records
// its value from its from-date (blank: the sheet's today), keeping the values recorded from other dates. The value in
// force on the sheet's today shows beside each. Saving sends only the settings whose fields were touched since the last save.
type SettingField = { key: string; label: string; placeholder: string; blank: boolean; valid: RegExp;
  inputMode: 'decimal' | 'numeric' | 'text'; invalid: string; dated?: false; starting?: string };

const SETTINGS: readonly SettingField[] = [
  { key: 'clerk-limit', label: 'Clerk limit', placeholder: 'no limit', blank: true, valid: AMOUNT, inputMode: 'decimal',
    invalid: 'A clerk limit is an amount with up to two decimals, or blank for no limit' },
  { key: 'floor', label: 'Floor', placeholder: FLOOR_DEFAULT, blank: false, valid: AMOUNT, inputMode: 'decimal',
    invalid: 'A floor is an amount with up to two decimals' },
  { key: 'terms', label: 'Terms (days)', placeholder: TERMS_DEFAULT, blank: false, valid: DAYS, inputMode: 'numeric',
    invalid: 'Terms are a whole number of days' },
  ...(['A', 'B', 'C'] as const).map((grade): SettingField => ({ key: `terms-${grade}`, label: `Terms for grade ${grade} (days)`,
    placeholder: 'sheet\'s terms', blank: true, valid: DAYS, inputMode: 'numeric',
    invalid: 'A grade\'s terms are a whole number of days, or blank for the sheet\'s terms' })),
  ...(['A', 'B', 'C'] as const).map((grade): SettingField => ({ key: `grace-${grade}`, label: `Grace for grade ${grade} (days)`,
    placeholder: 'none', blank: true, valid: DAYS, inputMode: 'numeric',
    invalid: 'A grade\'s grace is a whole number of days, or blank for none' })),
  { key: 'late-pct', label: 'Late percent', placeholder: LATE_PCT_DEFAULT, blank: false, valid: AMOUNT, inputMode: 'decimal',
    invalid: 'A late percent is a number with up to two decimals' },
  { key: 'policy-date', label: 'Policy date', placeholder: 'today', blank: true, valid: DATE, inputMode: 'text',
    invalid: 'A policy date is a date (yyyy-mm-dd), or blank for the sheet\'s today', dated: false },
  { key: 'period-numbering-from', label: 'Period numbering from', placeholder: 'off', blank: true, valid: DATE, inputMode: 'text',
    invalid: 'Period numbering from is a date (yyyy-mm-dd), or blank for off', dated: false },
  { key: 'entry-date', label: 'Entry date', placeholder: 'off', blank: true, valid: DATE, inputMode: 'text',
    invalid: 'An entry date is a date (yyyy-mm-dd), or blank for off', dated: false },
  { key: 'grace-days', label: 'Grace days', placeholder: 'off', blank: true, valid: DAYS, inputMode: 'numeric',
    invalid: 'Grace days are a whole number of days, or blank for off', dated: false },
  { key: 'fiscal-start-month', label: 'Fiscal year start month', placeholder: '1', blank: false, valid: /^(0?[1-9]|1[0-2])$/,
    inputMode: 'numeric', invalid: 'A fiscal start month is a month from 1 to 12', dated: false, starting: '1' },
  { key: 'cap', label: 'Cap', placeholder: 'none', blank: true, valid: AMOUNT, inputMode: 'decimal',
    invalid: 'A cap is an amount with up to two decimals, or blank for none' },
  { key: 'proof-threshold', label: 'Proof threshold', placeholder: 'none', blank: true, valid: AMOUNT, inputMode: 'decimal',
    invalid: 'A proof threshold is an amount with up to two decimals, or blank for none' },
  ...(['A', 'B', 'C'] as const).map((grade): SettingField => ({ key: `proof-threshold-${grade}`,
    label: `Proof threshold for grade ${grade}`, placeholder: 'sheet\'s threshold', blank: true, valid: AMOUNT, inputMode: 'decimal',
    invalid: 'A grade\'s proof threshold is an amount with up to two decimals, or blank for the sheet\'s' })),
  { key: 'note-threshold', label: 'Note threshold', placeholder: 'none', blank: true, valid: AMOUNT, inputMode: 'decimal',
    invalid: 'A note threshold is an amount with up to two decimals, or blank for none' },
  { key: 'pot', label: 'Pot', placeholder: 'none', blank: true, valid: AMOUNT, inputMode: 'decimal',
    invalid: 'A pot is an amount with up to two decimals, or blank for none', dated: false },
  { key: 'parent', label: 'Parent sheet', placeholder: 'none', blank: true, valid: SHEET_ID, inputMode: 'text',
    invalid: 'A parent is a sheet id, or blank for none', dated: false },
  ...([['open', 'clerk,steward'], ['settle', 'clerk,steward'], ['void', 'clerk,steward'], ['reassign', 'steward'],
    ['close', 'clerk,steward'], ['reopen', 'steward']] as const).map(([action, standing]): SettingField => ({
    key: `perm-${action}`, label: `Who may ${action}`, placeholder: standing, blank: true, valid: ROLE_LIST, inputMode: 'text',
    invalid: 'A permission is a comma separated list of roles (clerk, steward), or blank for the standing rule', dated: false })),
];

function SettingsPanel({ sheetId }: { sheetId: string; user: string }) {
  const settings = useSettings(sheetId);
  const [values, setValues] = useState<Record<string, string>>({});
  const [froms, setFroms] = useState<Record<string, string>>({});
  const [touched, setTouched] = useState<ReadonlySet<string>>(new Set());
  const [user] = useUser();
  const queryClient = useQueryClient();
  const current = (key: string) => (settings.data ?? []).find((s) => s.key === key)?.value ?? '';
  const touch = (key: string) => setTouched((t) => (t.has(key) ? t : new Set(t).add(key)));
  const save = useMutation({
    mutationFn: async (body: { keys: string[]; values: Record<string, string>; froms: Record<string, string> }) => {
      const changes = SETTINGS.filter((s) => body.keys.includes(s.key));
      if (changes.length === 0) throw new Error('Change a setting first');
      for (const s of changes) {
        const value = (body.values[s.key] ?? '').trim();
        if (value === '' ? !s.blank : !s.valid.test(value)) throw new Error(s.invalid);
        const from = (body.froms[s.key] ?? '').trim();
        if (from !== '' && !DATE.test(from)) throw new Error('A from-date is a date (yyyy-mm-dd), or blank for the sheet\'s today');
      }
      for (const s of changes) {
        await putJson<Setting>(`/api/sheets/${encodeURIComponent(sheetId)}/settings`,
          { key: s.key, value: (body.values[s.key] ?? '').trim(),
            ...(s.dated === false ? {} : { from: (body.froms[s.key] ?? '').trim() }), by: user ?? '' });
      }
    },
    onSuccess: async () => {
      setTouched(new Set());
      await queryClient.invalidateQueries({ queryKey: settingsKey(sheetId) });
      // The pot changes each pool member's cut.
      await queryClient.invalidateQueries({ queryKey: poolsKey(sheetId) });
      // The parent's rates stand in for the sheet's missing ones; the parent shows with the sheet's today.
      await queryClient.invalidateQueries({ queryKey: ratesKey(sheetId) });
      await queryClient.invalidateQueries({ queryKey: sheetTodayKey(sheetId) });
    },
  });
  const submit = useSubmitOnce(save);
  return (
    <section data-testid="settings-panel">
      <h2>Settings</h2>
      <form
        data-testid="settings-form"
        onSubmit={(e) => {
          e.preventDefault();
          submit({ keys: [...touched], values, froms });
        }}
      >
        {SETTINGS.map((s) => (
          <span key={s.key}>

